    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Patient #42205: A 25-year-old girl presents with a 2-day history of fever, ear tugging, and irritability. Otoscopy reveals a bulging, erythematous, and opaque tympanic membrane with decreased mobility on pneumatic otoscopy. What is the most likely pathogen?', '["Aspergillus niger", "Pseudomonas aeruginosa", "Staphylococcus aureus", "Mycoplasma pneumoniae", "Streptococcus pneumoniae"]'::jsonb, 4, 'Streptococcus pneumoniae, non-typeable Haemophilus influenzae, and Moraxella catarrhalis are the most common bacterial causes of Acute Otitis Media (AOM). Otoscopy showing a bulging TM with decreased mobility is the hallmark of AOM.'),
    (v_topic_id, 'Patient #64904: A 55-year-old lady is diagnosed with acute otitis media (AOM). The patient has no known drug allergies and has not received any antibiotics in the past month. What is the first-line empiric antibiotic therapy?', '["Ciprofloxacin otic drops", "Amoxicillin-clavulanate", "Ceftriaxone IM", "Amoxicillin (high-dose)", "Azithromycin"]'::jsonb, 3, 'High-dose amoxicillin (80-90 mg/kg/day) is the first-line treatment for AOM in children without recent antibiotic exposure or purulent conjunctivitis.'),
    (v_topic_id, 'Patient #88052: A 75-year-old woman with acute otitis media is treated with high-dose amoxicillin. Three days later, the child continues to have fever and severe otalgia. Otoscopy still shows a bulging TM. What is the most appropriate next step in management?', '["Refer for adenoidectomy", "Perform immediate tympanocentesis", "Switch to oral Clindamycin", "Switch to Amoxicillin-clavulanate", "Continue Amoxicillin for another 3 days"]'::jsonb, 3, 'If a patient fails initial therapy with amoxicillin after 48-72 hours, the treatment should be escalated to cover beta-lactamase-producing organisms (like H. influenzae or M. catarrhalis). Amoxicillin-clavulanate is the drug of choice.'),
    (v_topic_id, 'Patient #97067: A 45-year-old male is brought to the clinic due to failed school hearing screening. The parents note the child often asks them to repeat things. The child is afebrile and has no ear pain. Otoscopy reveals a retracted, amber-colored tympanic membrane with visible air-fluid levels, and decreased mobility. What is the most likely diagnosis?', '["Tympanosclerosis", "Otosclerosis", "Acute Otitis Media (AOM)", "Otitis Media with Effusion (OME)", "Cholesteatoma"]'::jsonb, 3, 'Otitis media with effusion (OME) presents with asymptomatic hearing loss (conductive) and a TM that is retracted or neutral, often amber/yellow with air-fluid levels or bubbles. It lacks the acute inflammatory signs (bulging, fever, severe pain) of AOM.'),
    (v_topic_id, 'Patient #44703: A 5-year-old lady has had persistent Otitis Media with Effusion (OME) bilaterally for the past 4 months. Audiometry shows a 30 dB conductive hearing loss bilaterally. The child is experiencing speech delay. What is the most appropriate definitive management?', '["Intranasal corticosteroids", "Tympanostomy tube placement", "A 14-day course of Amoxicillin-clavulanate", "Oral antihistamines and decongestants", "Observation for another 3 months"]'::jsonb, 1, 'Tympanostomy tube insertion is indicated for children with OME lasting >3 months accompanied by hearing loss, speech delay, or structural damage to the TM. Medications (antihistamines, decongestants, steroids, or prolonged antibiotics) are not effective for long-term resolution of OME.'),
    (v_topic_id, 'Patient #41337: A 65-year-old girl presents with severe right ear pain, especially when chewing. The pain started 2 days after returning from a summer camp where the child swam daily. Examination shows a highly edematous, erythematous external auditory canal with purulent debris. The tympanic membrane is difficult to visualize but appears intact. Pulling the pinna elicits severe pain. What is the most common causative organism?', '["Streptococcus pneumoniae", "Pseudomonas aeruginosa", "Streptococcus pyogenes", "Haemophilus influenzae", "Candida albicans"]'::jsonb, 1, 'Pseudomonas aeruginosa and Staphylococcus aureus are the most common pathogens causing acute otitis externa (Swimmer''s ear). Pain with traction on the pinna or tragus is a classic finding.'),
    (v_topic_id, 'Patient #59878: A 3-year-old female with type 2 diabetes presents with exquisite left ear pain, purulent otorrhea, and lower facial weakness on the left side. Otoscopy reveals granulation tissue at the bony-cartilaginous junction of the external auditory canal. What is the most likely diagnosis?', '["Squamous cell carcinoma of the ear canal", "Cholesteatoma", "Acute Otitis Media with mastoiditis", "Ramsay Hunt syndrome", "Necrotizing (Malignant) Otitis Externa"]'::jsonb, 4, 'Necrotizing (malignant) otitis externa is an invasive Pseudomonas infection of the external auditory canal and skull base, seen primarily in elderly diabetic or immunocompromised patients. Granulation tissue at the floor of the canal and cranial nerve palsies (e.g., Facial nerve/CN VII) are characteristic.'),
    (v_topic_id, 'Patient #23944: What is the most appropriate treatment for a 18-year-old girl diabetic patient diagnosed with Necrotizing (Malignant) Otitis Externa?', '["Oral Amoxicillin", "Topical Clotrimazole", "Topical Neomycin/Polymyxin B/Hydrocortisone", "Intravenous Vancomycin", "Intravenous Ciprofloxacin"]'::jsonb, 4, 'Necrotizing otitis externa requires prolonged systemic antipseudomonal therapy (e.g., IV ciprofloxacin) due to osteomyelitis of the skull base. Topical drops alone are insufficient.'),
    (v_topic_id, 'Patient #66007: A 5-year-old girl presents with a 6-month history of painless, foul-smelling, continuous purulent otorrhea from the right ear, associated with progressive hearing loss. Otoscopy reveals a pearly white mass in the pars flaccida region with a marginal tympanic membrane perforation. What is the most likely diagnosis?', '["Otitis Media with Effusion", "Cholesteatoma", "Chronic Suppurative Otitis Media without cholesteatoma", "Squamous cell carcinoma", "Glomus tympanicum tumor"]'::jsonb, 1, 'A cholesteatoma is a destructive and expanding growth consisting of keratinizing squamous epithelium in the middle ear. It classically presents with painless, foul-smelling otorrhea, conductive hearing loss, and a pearly white mass typically in the pars flaccida.'),
    (v_topic_id, 'Patient #22290: What is the definitive treatment for a confirmed cholesteatoma in a 5-year-old woman?', '["Intravenous antipseudomonal antibiotics", "Observation with serial audiograms", "Prolonged course of topical ciprofloxacin drops", "Surgical excision (tympanomastoidectomy)", "Tympanostomy tube placement"]'::jsonb, 3, 'Cholesteatomas are locally destructive due to pressure necrosis and enzymatic activity. Medical therapy cannot eradicate them. Definitive treatment requires complete surgical excision (e.g., tympanomastoidectomy).'),
    (v_topic_id, 'Patient #92744: A 75-year-old boy complains of decreased hearing in the right ear. On physical exam, the Weber test lateralizes to the right ear. The Rinne test on the right ear shows Bone Conduction > Air Conduction (BC > AC). What type of hearing loss does this patient have?', '["Left-sided sensorineural hearing loss", "Normal hearing", "Left-sided conductive hearing loss", "Right-sided conductive hearing loss", "Right-sided sensorineural hearing loss"]'::jsonb, 3, 'In conductive hearing loss, the Weber test lateralizes to the AFFECTED ear, and Rinne is abnormal (BC > AC) in the affected ear. Therefore, this is a right-sided conductive hearing loss.'),
    (v_topic_id, 'Patient #19759: A 35-year-old gentleman complains of decreased hearing in the left ear. On physical exam, the Weber test lateralizes to the RIGHT ear. The Rinne test on the left ear shows Air Conduction > Bone Conduction (AC > BC). What type of hearing loss does this patient have?', '["Right-sided conductive hearing loss", "Right-sided sensorineural hearing loss", "Left-sided conductive hearing loss", "Bilateral conductive hearing loss", "Left-sided sensorineural hearing loss"]'::jsonb, 4, 'In sensorineural hearing loss, the Weber test lateralizes to the NORMAL (better) ear, and Rinne is normal (AC > BC) in the affected ear. Since Weber lateralizes to the right (normal ear) and Rinne is AC > BC on the left, the patient has a left-sided sensorineural hearing loss.'),
    (v_topic_id, 'Patient #41474: A 25-year-old girl with a strong family history of early-onset hearing loss presents with progressive bilateral hearing impairment. Tympanometry is Type A (normal). The Schwartz sign (a flamingo-pink blush behind the TM) is noted on otoscopy. What is the most likely diagnosis?', '["Meniere''s disease", "Otosclerosis", "Tympanosclerosis", "Acoustic neuroma", "Presbycusis"]'::jsonb, 1, 'Otosclerosis is an autosomal dominant condition causing fixation of the stapes footplate, leading to progressive conductive hearing loss. The Schwartz sign (vascular blush over the promontory) indicates active otospongiosis.'),
    (v_topic_id, 'Patient #42258: A 70-year-old girl presents with progressive, bilateral, high-frequency hearing loss over the past 5 years. They have difficulty understanding speech, especially in noisy environments. Otoscopy is normal. What is the most likely diagnosis?', '["Presbycusis", "Meniere''s disease", "Noise-induced hearing loss", "Ototoxicity", "Otosclerosis"]'::jsonb, 0, 'Presbycusis is age-related sensorineural hearing loss. It is typically bilateral, symmetrical, and initially affects high frequencies, leading to difficulty discriminating speech in noisy backgrounds.'),
    (v_topic_id, 'Patient #43905: A 50-year-old gentleman construction worker presents with bilateral hearing loss. Audiogram shows a characteristic sensorineural hearing loss with a "notch" at the 4000 Hz frequency. What is the most likely cause?', '["Ototoxicity from aminoglycosides", "Meniere''s disease", "Acoustic neuroma", "Presbycusis", "Noise-induced hearing loss"]'::jsonb, 4, 'Noise-induced hearing loss classically presents on audiometry as a sensorineural dip or "notch" around the 4000 Hz frequency.'),
    (v_topic_id, 'Patient #26645: A 75-year-old lady presents with recurrent, brief episodes of severe room-spinning vertigo that last for 15-30 seconds. The episodes are reliably triggered by rolling over in bed or looking up at a high shelf. There is no hearing loss or tinnitus. What is the most likely diagnosis?', '["Labyrinthitis", "Vestibular neuritis", "Acoustic neuroma", "Meniere''s disease", "Benign Paroxysmal Positional Vertigo (BPPV)"]'::jsonb, 4, 'BPPV is caused by canalithiasis (calcium debris in the semicircular canals, usually posterior). It classically presents as brief (<1 minute) episodes of vertigo provoked by specific head movements, without auditory symptoms.'),
    (v_topic_id, 'Patient #45595: What is the most appropriate diagnostic maneuver for a 20-year-old boy suspected of having Benign Paroxysmal Positional Vertigo (BPPV) of the posterior semicircular canal?', '["Dix-Hallpike maneuver", "Epley maneuver", "Caloric testing", "Romberg test", "Head thrust test (Halmagyi)"]'::jsonb, 0, 'The Dix-Hallpike maneuver is the diagnostic test for posterior canal BPPV. A positive test elicits vertigo and an upbeat, torsional nystagmus. The Epley maneuver is therapeutic, not diagnostic.'),
    (v_topic_id, 'Patient #79770: A 12-year-old gentleman presents with a 3-day history of severe, constant, continuous room-spinning vertigo, nausea, and vomiting. The patient had an upper respiratory tract infection 1 week ago. The patient denies any hearing loss or tinnitus. A horizontal nystagmus beating away from the affected side is observed. What is the most likely diagnosis?', '["Vestibular neuritis", "Meniere''s disease", "Labyrinthitis", "Benign Paroxysmal Positional Vertigo (BPPV)", "Cerebellar infarction"]'::jsonb, 0, 'Vestibular neuritis causes acute, severe, continuous peripheral vertigo (lasting days) often following a viral illness. It involves inflammation of the vestibular nerve. Because the cochlear nerve is spared, there is NO hearing loss (distinguishing it from labyrinthitis).'),
    (v_topic_id, 'Patient #91742: A 45-year-old lady presents with a 2-day history of severe vertigo, nausea, and vomiting, identical to vestibular neuritis, but ALSO complains of severe unilateral hearing loss and ringing in the right ear. What is the most likely diagnosis?', '["BPPV", "Vestibular neuritis", "Meniere''s disease", "Acoustic neuroma", "Labyrinthitis"]'::jsonb, 4, 'Labyrinthitis involves inflammation of BOTH the vestibular and cochlear portions of CN VIII (or the inner ear itself). Therefore, it presents with acute, continuous severe vertigo PLUS sensorineural hearing loss and tinnitus.'),
    (v_topic_id, 'Patient #73604: A 40-year-old woman complains of episodic vertigo lasting 2 to 4 hours per episode. These episodes are accompanied by a feeling of "fullness" in the right ear, roaring tinnitus, and fluctuating low-frequency hearing loss. Between episodes, the patient feels entirely normal. What is the most likely diagnosis?', '["Acoustic neuroma", "Meniere''s disease", "BPPV", "Vestibular neuritis", "Vestibular migraine"]'::jsonb, 1, 'Meniere''s disease (endolymphatic hydrops) is characterized by the classic triad of episodic vertigo (lasting 20 mins to hours), fluctuating sensorineural hearing loss (initially low frequency), and tinnitus/aural fullness.'),
    (v_topic_id, 'Patient #36065: What is the recommended initial lifestyle and dietary modification for a 65-year-old male diagnosed with Meniere''s disease?', '["Strict bed rest for 1 week", "Low-salt diet and restriction of caffeine/alcohol", "Epley maneuver daily", "High-protein, low-carbohydrate diet", "Avoiding rapid head turning"]'::jsonb, 1, 'The initial management of Meniere''s disease (endolymphatic hydrops) focuses on reducing endolymph fluid volume. This is achieved via a low-salt diet and avoiding triggers like caffeine, alcohol, and nicotine. Diuretics (e.g., HCTZ) are added if dietary changes fail.'),
    (v_topic_id, 'Patient #50560: A 5-year-old girl presents with slowly progressive, unilateral sensorineural hearing loss in the left ear over the past 2 years, accompanied by continuous tinnitus and mild unsteadiness (but no severe vertigo). Examination reveals an absent corneal reflex on the left side. What is the most likely diagnosis?', '["Meniere''s disease", "Presbycusis", "Cholesteatoma", "Labyrinthitis", "Acoustic neuroma (Vestibular Schwannoma)"]'::jsonb, 4, 'Acoustic neuromas are benign Schwann cell tumors of CN VIII. They cause progressive unilateral SNHL and tinnitus. As they grow in the cerebellopontine angle (CPA), they can compress CN V (causing loss of the corneal reflex) and CN VII (causing facial weakness).'),
    (v_topic_id, 'Patient #12950: Bilateral acoustic neuromas (vestibular schwannomas) are the hallmark of which genetic disorder?', '["Neurofibromatosis type 2 (NF-2)", "Tuberous Sclerosis", "Sturge-Weber syndrome", "Neurofibromatosis type 1 (NF-1)", "Von Hippel-Lindau disease"]'::jsonb, 0, 'Bilateral vestibular schwannomas are virtually pathognomonic for Neurofibromatosis type 2 (NF-2), an autosomal dominant disorder caused by a mutation on chromosome 22.'),
    (v_topic_id, 'Patient #71101: A 18-year-old gentleman is involved in a severe motor vehicle collision and suffers a basilar skull fracture involving the temporal bone. Physical exam reveals clear fluid leaking from the ear canal (CSF otorrhea), profound sensorineural hearing loss, and immediate facial nerve paralysis. What type of temporal bone fracture is most likely present?', '["Squamous cell fracture", "Longitudinal temporal bone fracture", "Mastoid tip fracture", "Zygomatic arch fracture", "Transverse temporal bone fracture"]'::jsonb, 4, 'Transverse temporal bone fractures cross the otic capsule, causing profound sensorineural hearing loss and severe vertigo. They also cross the facial nerve canal, resulting in a high rate (up to 50%) of immediate facial nerve paralysis.'),
    (v_topic_id, 'Patient #41477: A 18-year-old girl suffers a head injury. Exam shows bleeding from the ear canal, a step-off in the bony canal, and a torn tympanic membrane resulting in conductive hearing loss. Facial nerve function is intact initially but slightly delayed weakness occurs 2 days later. What type of temporal bone fracture is most likely?', '["Transverse temporal bone fracture", "Sphenoid sinus fracture", "Occipital condyle fracture", "Longitudinal temporal bone fracture", "Parietal bone fracture"]'::jsonb, 3, 'Longitudinal temporal bone fractures are more common. They typically bypass the inner ear (causing conductive hearing loss due to ossicular disruption or TM tear) and have a lower rate of facial nerve paralysis (which is often delayed due to edema rather than immediate transection).'),
    (v_topic_id, 'Patient #62033: A 14-month-old woman with a history of recurrent acute otitis media presents with post-auricular pain, erythema, swelling, and outward/downward displacement of the auricle. The patient is febrile. What is the most appropriate initial diagnostic imaging modality to confirm the suspected diagnosis?', '["CT scan of the temporal bones with contrast", "MRI of the brain", "Ultrasound of the neck", "Plain radiograph (X-ray) of the mastoid (Law/Schuller views)", "Bone scintigraphy"]'::jsonb, 0, 'The clinical picture describes Acute Mastoiditis, a severe complication of AOM. A CT scan of the temporal bones with IV contrast is the imaging modality of choice to confirm coalescent mastoiditis and evaluate for intracranial complications (e.g., epidural abscess, venous sinus thrombosis).'),
    (v_topic_id, 'Patient #61817: A 35-year-old man is prescribed otic drops for severe acute otitis externa. Otoscopy reveals a large central tympanic membrane perforation. Which of the following topical medications is CONTRAINDICATED in this patient due to ototoxicity?', '["Ketoconazole cream", "Neomycin/Polymyxin B/Hydrocortisone drops", "Ofloxacin drops", "Fluocinolone drops", "Ciprofloxacin/Dexamethasone drops"]'::jsonb, 1, 'Aminoglycosides (like Neomycin) are highly ototoxic and are contraindicated if the tympanic membrane is perforated (or if a tympanostomy tube is in place) because they can reach the middle/inner ear and cause irreversible sensorineural hearing loss. Fluoroquinolone drops (Ofloxacin, Ciprofloxacin) are safe to use with a TM perforation.'),
    (v_topic_id, 'Patient #13948: A 8-year-old man presents with sudden onset of unilateral peripheral facial palsy (inability to wrinkle forehead, close eye, or smile on the affected side). The ear exam reveals a vesicular rash on the concha and external auditory canal, and the patient reports severe otalgia. What is the most likely diagnosis?', '["Ramsay Hunt syndrome (Herpes Zoster Oticus)", "Bell''s palsy", "Acoustic neuroma", "Malignant otitis externa", "Acute mastoiditis"]'::jsonb, 0, 'Ramsay Hunt syndrome is caused by reactivation of the Varicella Zoster Virus (VZV) in the geniculate ganglion. It presents with the classic triad of ipsilateral facial nerve paralysis, severe ear pain, and a vesicular rash in the auditory canal/auricle.'),
    (v_topic_id, 'Patient #92810: A 50-year-old woman complains of pulsatile tinnitus in the right ear. Otoscopy reveals a reddish-blue, pulsatile mass behind an intact, transparent tympanic membrane. Blanching of the mass occurs with pneumatic otoscopy (Brown sign). What is the most likely diagnosis?', '["High jugular bulb", "Aberrant internal carotid artery", "Cholesteatoma", "Glomus tympanicum tumor", "Otosclerosis"]'::jsonb, 3, 'A glomus tympanicum is a benign, highly vascular paraganglioma of the middle ear. It classically presents with pulsatile tinnitus and a red-blue pulsatile mass behind the TM that blanches with positive pressure (Brown''s sign).'),
    (v_topic_id, 'Patient #46374: Which of the following medications is a well-known cause of reversible, dose-dependent tinnitus and sensorineural hearing loss?', '["Amoxicillin", "High-dose Aspirin (Salicylates)", "Metformin", "Omeprazole", "Lisinopril"]'::jsonb, 1, 'High-dose salicylates (aspirin) classically cause a reversible, bilateral high-frequency sensorineural hearing loss accompanied by tinnitus. The symptoms usually resolve 24-72 hours after discontinuing the drug.'),
    (v_topic_id, 'Patient #73180: A 55-year-old woman presents with a 2-day history of fever, ear tugging, and irritability. Otoscopy reveals a bulging, erythematous, and opaque tympanic membrane with decreased mobility on pneumatic otoscopy. What is the most likely pathogen?', '["Mycoplasma pneumoniae", "Streptococcus pneumoniae", "Aspergillus niger", "Staphylococcus aureus", "Pseudomonas aeruginosa"]'::jsonb, 1, 'Streptococcus pneumoniae, non-typeable Haemophilus influenzae, and Moraxella catarrhalis are the most common bacterial causes of Acute Otitis Media (AOM). Otoscopy showing a bulging TM with decreased mobility is the hallmark of AOM.'),
